#include "galaxybridge_internet.h"
#include <assert.h>
int main(void){gb_gateway_pool_reset();assert(gb_gateway_flow_acquire(1,-1,1)==-1);gb_gateway_pool_update(0,1,1);gb_gateway_pool_update(1,1,2);assert(gb_gateway_flow_acquire(1,-1,1)==0);assert(gb_gateway_flow_acquire(2,-1,1)==1);gb_gateway_pool_update(0,0,1);assert(gb_gateway_flow_acquire(1,-1,1)==0);assert(gb_gateway_flow_acquire(3,-1,1)==1);assert(gb_gateway_flow_acquire(4,0,1)==-1);gb_gateway_flow_release(1);assert(gb_gateway_flow_acquire(1,-1,0)==1);
 gb_gateway_pool_reset();assert(gb_internet_tunnel_set_gateways(1234,5678,3,2,0)==0);assert(gb_gateway_flow_port(10,1)==1234);assert(gb_gateway_flow_port(11,1)==5678);assert(gb_internet_tunnel_set_gateways_checked(9999,5678,3,2,0,1)!=0);assert(gb_internet_tunnel_set_gateways(9999,5678,2,2,0)==0);assert(gb_gateway_flow_port(10,1)==1234);assert(gb_gateway_flow_port(12,1)==5678);gb_gateway_flow_release(10);assert(gb_internet_tunnel_set_gateways_checked(9999,5678,3,2,0,1)==0);uint32_t counts[2];gb_gateway_pool_stats(counts);assert(counts[0]==0&&counts[1]==2);uint64_t started[2];gb_gateway_pool_total_started(started);assert(started[0]==1&&started[1]==2);return 0;}
